import { RawSecondaryLesson } from './curriculumSecondary';

/**
 * PHÂN PHỐI CHƯƠNG TRÌNH CHI TIẾT MÔN KHOA HỌC TỰ NHIÊN (KHTN) THCS (LỚP 6, 7, 8, 9)
 * 100% CHUẨN XÁC THEO TỪNG BÀI HỌC VÀ SỐ TIẾT TÀI LIỆU KHOA HỌC TỰ NHIÊN (KNTT)
 * CÁC BÀI KIỂM TRA ĐÁNH GIÁ ĐỊNH KỲ CHUẨN 2 TIẾT (90 PHÚT) THEO QUY ĐỊNH BỘ GD&ĐT
 *
 * Cấu trúc tuần kiểm tra định kỳ (Tuần 9, 16, 26, 31):
 * - Ôn tập củng cố chuẩn bị kiểm tra: 2 tiết
 * - Kiểm tra, đánh giá định kỳ (Giữa kì 1, Cuối kì 1, Giữa kì 2, Cuối kì 2): 2 tiết
 *
 * Tích hợp chuẩn 100%:
 * - Yêu cầu cần đạt (YCCĐ) chuẩn Chương trình GDPT 2018 môn KHTN (Thông tư 32/2018/TT-BGDĐT)
 * - Khung Năng lực số (NLS) theo Công văn 3456/BGDĐT-GDPT (Lớp 6, 7: Mức TC1; Lớp 8, 9: Mức TC2)
 * - Khung Năng lực AI theo Quyết định 2422/QĐ-BGDĐT (Phân theo từng khối lớp và chủ đề bài học)
 * - Tối ưu hiển thị đồng bộ tuyệt đối trên Phụ lục 1 (Tổ chuyên môn) và Phụ lục 3 (Kế hoạch giáo viên)
 */

